CREATE TABLE USERS (
    ID NUMBER PRIMARY KEY,
    EMAIL VARCHAR2(255) NOT NULL UNIQUE,
    CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    NOTE VARCHAR2(100) COMMENT 'User notes'
);

CREATE TABLE ORDERS (
    ID NUMBER PRIMARY KEY,
    USER_ID NUMBER NOT NULL,
    AMOUNT NUMBER(10,2) DEFAULT 0,
    CONSTRAINT FK_ORDERS_USER FOREIGN KEY (USER_ID) REFERENCES USERS(ID)
);

CREATE INDEX IDX_ORDERS_USER ON ORDERS(USER_ID);

ALTER TABLE USERS ADD LAST_LOGIN TIMESTAMP;

DROP INDEX IDX_ORDERS_USER;

-- Unsupported: ALTER TABLE ... ADD COLUMN with generated identity
ALTER TABLE USERS ADD GENERATED_ID NUMBER GENERATED ALWAYS AS IDENTITY;
